def safe_calc(a, op, b):
    try:
        if op == "+":
            return a + b
        elif op == "-":
            return a - b
        elif op == "*":
            return a * b
        elif op == "/":
            return a / b
        else:
            raise ValueError
    except ZeroDivisionError:
        return "0으로 나눌 수 없어요"
    except TypeError:
        return "숫자가 아니에요"
    except ValueError:
        return "지원하지 않는 연산"

